window.B1=[{"n": 1, "title": "Have you ever…?", "setting": "Andrés and Sofía are looking at photos on Sofía’s phone. Use the verbs in brackets.", "lines": [{"who": "Andrés", "parts": ["Wow, is that you on a zipline? ", {"num": "1"}, {"gap": "you / ever / do"}, " that before?"]}, {"who": "Sofía", "parts": ["No, it was my first time! I ", {"num": "2"}, {"gap": "never / be"}, " so scared in my life."]}, {"who": "Andrés", "parts": ["Where was it?"]}, {"who": "Sofía", "parts": ["In Jarabacoa. We ", {"num": "3"}, {"gap": "go"}, " there last weekend with my cousins."]}, {"who": "Andrés", "parts": ["Cool! I ", {"num": "4"}, {"gap": "be"}, " to Jarabacoa, but I ", {"num": "5"}, {"gap": "not / try"}, " the zipline."]}, {"who": "Sofía", "parts": ["You have to! ", {"num": "6"}, {"gap": "you / ever / climb"}, " Pico Duarte?"]}, {"who": "Andrés", "parts": ["Not yet. But my brother ", {"num": "7"}, {"gap": "just / come"}, " back from there. He loved it!"]}], "after": "Listen again and check. Then act it out with a partner and change the adventure: surfing, scuba diving, horse riding .", "ansT": {"1": "Have you ever done", "2": "have never been", "3": "went", "4": "have been", "5": "haven’t tried", "6": "Have you ever climbed", "7": "has just come"}, "pairs": ["🐋 seen a whale in Samaná", "🏔️ climbed a mountain", "🍳 cooked for your family", "✈️ flown in a plane", "🎤 sung in public", "⭐ met a famous person"], "sound": ["have → ’ve: I’ve · you’ve · we’ve · they’ve", "has → ’s: she’s been · he’s seen · it’s gone", "Careful! She’s eaten = she has eaten. She’s hungry = she is hungry."], "rtitle": "Teens Who Have Done It!", "rsub": "Three young Dominicans share their biggest adventures", "paras": ["Some teens spend the weekend on their phones. Others go out and try something new. We asked three young Dominicans about the most exciting things they have done.", "Mateo, 15, Santiago. “I’ve climbed Pico Duarte twice! It’s the highest mountain in the Caribbean. The first time, I was very tired, but when I saw the sunrise above the clouds, I forgot everything. I haven’t climbed any other mountain yet, but I want to try Pico Turquino in Cuba.”", "Luisa, 14, Samaná. “I’ve seen humpback whales many times because they come to Samaná every winter. Last year I volunteered with a group that protects them. I’ve learned so much about the ocean!”", "Kevin, 16, Santo Domingo. “I’ve just finished my first short film with my friends. We’ve shown it at school and now we want to send it to a festival. I’ve never worked so hard on anything, but it’s been the best experience of my life.”"], "pull": "“I’ve never felt so free in my life.”", "atitle": "A. Who…? Write M (Mateo), L (Luisa) or K (Kevin).", "qa": ["1. has done something many times. ____", "2. has worked on a creative project. ____", "3. wants to visit another country. ____", "4. has helped to protect animals. ____"], "qb": ["5. Mateo has climbed Pico Turquino. ____", "6. Luisa has been to Cuba. ____", "7. Kevin’s film has won a prize. ____"], "qc": "Underline five present perfect verbs. Which adventure would you choose? Why?", "ansR": {"1": "L", "2": "K", "3": "M", "4": "L", "5": "F", "6": "DS", "7": "DS"}, "ansR_raw": "Answers 7: 1 L · 2 K · 3 M · 4 L · 5 F · 6 DS · 7 DS", "sub": "Experiences, adventures and things you’ve never done"}, {"n": 2, "title": "How long have you…?", "setting": "Javier arrives late to baseball practice. Use the verbs in brackets.", "lines": [{"who": "Coach", "parts": ["Javier! We ", {"num": "1"}, {"gap": "wait"}, " for you for twenty minutes!"]}, {"who": "Javier", "parts": ["Sorry, coach. I ", {"num": "2"}, {"gap": "help"}, " my grandma since lunch."]}, {"who": "Coach", "parts": ["OK. Your team ", {"num": "3"}, {"gap": "practice"}, " hitting all afternoon. They’re tired."]}, {"who": "Javier", "parts": ["I can see that! How long ", {"num": "4"}, {"gap": "Daniela / play"}, " on the team?"]}, {"who": "Coach", "parts": ["She ", {"num": "5"}, {"gap": "be"}, " with us since March. She’s great!"]}, {"who": "Javier", "parts": ["I ", {"num": "6"}, {"gap": "know"}, " her for years. We’re neighbors."]}], "after": "Listen again and check. Then act it out with a partner and change the sport: basketball, volleyball, dance .", "ansT": {"1": "have been waiting", "2": "have been helping", "3": "has been practicing", "4": "has Daniela been playing", "5": "has been", "6": "have known"}, "pairs": ["🏠 live in your house", "🤝 know your best friend", "🇬🇧 learn English", "📱 have your phone", "🎮 play your favorite game", "⚽ do your favorite sport"], "sound": ["In fast speech, been sounds like /bɪn/ and for sounds like /fə/.", "Say it fast! I’ve /bɪn/ waiting /fə/ ages!", "She’s /bɪn/ playing /fə/ two hours."], "rtitle": "The Mural Kids of the Zona Colonial", "rsub": "They have been painting their neighborhood for three years", "paras": ["Walk down a quiet street in the Zona Colonial and you will see something special: bright walls full of birds, flowers, music and faces. They are the work of a group of teenagers called The Mural Kids .", "The group started in 2023, when five friends from the same school decided to paint an old gray wall near their homes. “We’ve been painting every Saturday since then,” says Ana, 15. “So far, we’ve finished eleven murals.”", "Their neighbors have been helping too. Some give them paint, others bring food and cold drinks. “Mr. Ramírez has lived on this street for forty years,” explains Luis, 14. “He says the neighborhood has never looked so happy.”", "The project has grown a lot. Twelve teens have joined the group, and a local artist has been teaching them new techniques for six months. Their dream? “We want to paint a mural in every school in Santo Domingo!”"], "pull": "“We’ve been painting every Saturday since then.”", "atitle": "A. Answer the questions.", "qa": ["1. When did the group start?", "2. How many murals have they finished?", "3. How long has Mr. Ramírez lived on the street?", "4. Who has been teaching them for six months?"], "qb": ["5. The group paints every Sunday. ____", "6. Some neighbors bring food. ____", "7. Ana wants to be a professional artist. ____"], "qc": "Find three examples of for or since in the text.", "ansR": {"1": "in 2023", "2": "eleven", "3": "for forty years", "4": "a local artist", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 in 2023 · 2 eleven · 3 for forty years · 4 a local artist · 5 F · 6 T · 7 DS", "sub": "Hobbies, habits and things that started in the past"}, {"n": 3, "title": "As good as…", "setting": "Valeria and Marcos are choosing new sneakers for the school race.", "lines": [{"who": "Valeria", "parts": ["Look at these two! They look ", {"num": "1"}, {"gap": ""}, ", but the price is very different."]}, {"who": "Marcos", "parts": ["The blue ones are ", {"num": "2"}, {"gap": ""}, " cheaper — only 2,500 pesos."]}, {"who": "Valeria", "parts": ["But they aren’t ", {"num": "3"}, {"gap": ""}, " light ", {"num": "4"}, {"gap": ""}, " the red ones."]}, {"who": "Marcos", "parts": ["True. The red ones are ", {"num": "5"}, {"gap": ""}, " lighter — just 20 grams."]}, {"who": "Valeria", "parts": ["Hmm, my old sneakers are the same ", {"num": "6"}, {"gap": ""}, " the blue ones. I’ll try the red ones!"]}, {"who": "Marcos", "parts": ["Good idea. They look ", {"num": "7"}, {"gap": ""}, " the ones professional runners use."]}], "after": "Word box: alike · much · as · as · a bit · as · like", "ansT": {"1": "alike", "2": "much", "3": "as", "4": "as", "5": "a bit", "6": "as", "7": "like"}, "pairs": ["⚾ baseball vs. 🏀 basketball", "🏖️ the beach vs. 🏔️ the mountains", "📱 phones vs. 💻 laptops", "🍕 pizza vs. 🍚 la bandera", "🎬 movies vs. 📺 series", "🚌 the bus vs. 🚇 the metro"], "sound": ["In as … as , both words are short and weak: /əz/.", "Say it fast! She’s /əz/ fast /əz/ me.", "It isn’t /əz/ hot /əz/ yesterday."], "rtitle": "Two Runners, One Dream", "rsub": "Twins from San Pedro de Macorís — alike, but not the same", "paras": ["Rosa and Rafael Peña are fifteen-year-old twins from San Pedro de Macorís, a city famous for its baseball players. But the twins don’t play baseball. They run — and they run fast.", "People often say the twins look exactly alike, and it’s true: they have the same smile and the same curly hair. But on the track, they are very different. Rafael is a bit taller than his sister and much stronger at the start. Rosa isn’t as fast as Rafael in short races, but she is far better at long distances.", "“Running with my brother is great,” says Rosa. “When I’m tired, he pushes me. When he wants to stop, I don’t let him.” Their coach agrees: “Rafael is as talented as Rosa, but they need different kinds of training.”", "Next year, both of them want to compete at the Central American Games. “We’re not the same,” says Rafael, “and that’s our secret.”"], "pull": "“We’re not the same, and that’s our secret.”", "atitle": "A. Who…? Write R (Rosa) or F (Rafael).", "qa": ["1. is a bit taller. ____", "2. is better at long distances. ____", "3. is stronger at the start. ____", "4. helps the other one when tired. ____"], "qb": ["5. The twins play baseball. ____", "6. The twins look very similar. ____", "7. Their coach is their father. ____"], "qc": "Underline four comparisons in the text.", "ansR": {"1": "F", "2": "R", "3": "F", "4": "R (and F)", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 F · 2 R · 3 F · 4 R (and F) · 5 F · 6 T · 7 DS", "sub": "Comparing people, places, sports and things"}, {"n": 4, "title": "The future", "setting": "Gabriela and Tomás are preparing for the school science fair.", "lines": [{"who": "Gabriela", "parts": ["So, what ", {"num": "1"}, {"gap": "we / do"}, " for the science fair?"]}, {"who": "Tomás", "parts": ["I’ve decided! We ", {"num": "2"}, {"gap": "build"}, " a small robot that waters plants."]}, {"who": "Gabriela", "parts": ["Cool! Do you think it ", {"num": "3"}, {"gap": "work"}, "?"]}, {"who": "Tomás", "parts": ["I hope so. I think the judges ", {"num": "4"}, {"gap": "love"}, " it."]}, {"who": "Gabriela", "parts": ["Oh no, my laptop battery is at 2%! It ", {"num": "5"}, {"gap": "die"}, "!"]}, {"who": "Tomás", "parts": ["Don’t worry, I ", {"num": "6"}, {"gap": "get"}, " my charger."]}, {"who": "Gabriela", "parts": ["Thanks! I promise I ", {"num": "7"}, {"gap": "not / be"}, " late tomorrow."]}], "after": "Listen again and check. Why is it will or going to each time? Discuss with a partner.", "ansT": {"1": "are we going to do", "2": "are going to build", "3": "will work", "4": "will love", "5": "’s going to die", "6": "’ll get", "7": "won’t be"}, "pairs": ["🌙 What are you going to do tonight?", "🎓 What are you going to study?", "🏖️ What are you going to do on vacation?", "🤖 Will robots teach in schools?", "🚗 Will cars fly in 2070?", "🌎 Will people live on Mars?"], "sound": ["I’ll /aɪl/ · you’ll /juːl/ · it’ll /ˈɪtl/", "won’t /woʊnt/ — don’t confuse it with want !", "Say it fast! I’ll help you, but I won’t do it for you."], "rtitle": "School in 2070: What Will It Be Like?", "rsub": "Three experts share their predictions", "paras": ["What will school look like when today’s teenagers are grandparents? We asked three experts to make their predictions.", "Dr. Carmen Liriano, education expert. “Students won’t carry heavy backpacks. Every student will have a light tablet with all their books inside. But I don’t think teachers will disappear. Young people will always need a person who listens to them.”", "Ing. Pedro Almonte, engineer. “Robots will help in classrooms, but they won’t replace teachers. My team is going to test a robot assistant in five schools in Santiago next year. It’s going to help students with math.”", "Lic. Sofía Reyes, environmental scientist. “Schools will be greener. They’ll have solar panels and gardens on the roof. In fact, the Ministry is going to start a solar school program in 2027.”"], "pull": "“Young people will always need a person who listens to them.”", "atitle": "A. Who…? Write C (Carmen), P (Pedro) or S (Sofía).", "qa": ["1. talks about a plan for next year. ____", "2. thinks teachers won’t disappear. ____", "3. talks about the environment. ____", "4. works with robots. ____"], "qb": ["5. two predictions with will: ____________", "6. two plans with going to: ____________"], "qc": "Which prediction do you agree with most? Why?", "ansR": {"1": "P (and S)", "2": "C", "3": "S", "4": "P"}, "ansR_raw": "Answers 8: 1 P (and S) · 2 C · 3 S · 4 P", "sub": "Predictions, plans, promises and quick decisions"}, {"n": 5, "title": "This time tomorrow…", "setting": "Isabel and Carlos are planning to meet on Saturday. Use the verbs in brackets.", "lines": [{"who": "Isabel", "parts": ["Can we meet on Saturday morning? Or ", {"num": "1"}, {"gap": "you / work"}, "?"]}, {"who": "Carlos", "parts": ["Yes, from 8 to 12 I ", {"num": "2"}, {"gap": "help"}, " my uncle at his colmado."]}, {"who": "Isabel", "parts": ["OK. And in the afternoon?"]}, {"who": "Carlos", "parts": ["At 3 I ", {"num": "3"}, {"gap": "play"}, " basketball with the team."]}, {"who": "Isabel", "parts": ["Hmm… what about 6? I ", {"num": "4"}, {"gap": "not / do"}, " anything then."]}, {"who": "Carlos", "parts": ["Perfect! I ", {"num": "5"}, {"gap": "wait"}, " for you at the park."]}], "after": "Listen again and check. Then plan your own Saturday with a partner.", "ansT": {"1": "will you be working", "2": "’ll be helping", "3": "’ll be playing", "4": "won’t be doing", "5": "’ll be waiting"}, "pairs": ["⏰ at 6 a.m. tomorrow", "🏫 at 10 a.m. on Monday", "🍽️ at dinner time tonight", "🎉 on New Year’s Eve", "🎓 this time next year", "🌍 in ten years"], "sound": ["I’ll be /aɪl bi/ — link them together!", "Say it fast! I’ll be working · She’ll be sleeping · We’ll be waiting."], "rtitle": "Tomorrow I’ll Be Flying to Madrid!", "rsub": "A student’s blog the night before her exchange trip", "paras": ["My name is Paola and I’m sixteen. Tomorrow is the big day: my school exchange to Spain! I can’t sleep, so I’m writing this post instead.", "Here’s my plan. At 6 a.m. my parents will be driving me to Las Américas airport. At 9 a.m. I’ll be sitting on the plane, probably watching movies, and by tomorrow night I’ll be flying over the Atlantic Ocean.", "For the next three months, I’ll be living with a host family in Madrid. Their daughter, Lucía, is my age. We’ve been texting for weeks! On weekdays, I’ll be going to her school, and on weekends we’ll be visiting museums and parks.", "Will I miss home? Of course! I’ll be missing my mom’s food every day. But this time next week, I’ll be eating churros in Madrid — not bad at all!"], "pull": "“This time next week, I’ll be eating churros in Madrid!”", "atitle": "A. Answer the questions.", "qa": ["1. Where is Paola going?", "2. Who will be driving her to the airport?", "3. How long will she be living in Madrid?", "4. What will she be doing on weekends?"], "qb": ["5. Paola is going to study in Madrid for a year. ____", "6. Lucía and Paola have been texting. ____", "7. Paola has been to Spain before. ____"], "qc": "Underline four examples of the future continuous.", "ansR": {"1": "to Spain / Madrid", "2": "her parents", "3": "three months", "4": "visiting museums and parks", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 to Spain / Madrid · 2 her parents · 3 three months · 4 visiting museums and parks · 5 F · 6 T · 7 DS", "sub": "Actions in progress at a moment in the future"}, {"n": 6, "title": "If it rains…", "setting": "Camila and Diego are planning a trip to Boca Chica on Saturday.", "lines": [{"who": "Camila", "parts": ["Are we still going to Boca Chica on Saturday?"]}, {"who": "Diego", "parts": ["Yes! But if it ", {"num": "1"}, {"gap": "rain"}, ", we ", {"num": "2"}, {"gap": "stay"}, " home."]}, {"who": "Camila", "parts": ["The app says it might rain in the morning. If we ", {"num": "3"}, {"gap": "leave"}, " after lunch, we ", {"num": "4"}, {"gap": "miss"}, " the rain."]}, {"who": "Diego", "parts": ["Good idea. If my mom ", {"num": "5"}, {"gap": "drive"}, " us, we ", {"num": "6"}, {"gap": "not / need"}, " the bus."]}, {"who": "Camila", "parts": ["Perfect! I’ll bring snacks if you ", {"num": "7"}, {"gap": "bring"}, " the speaker."]}, {"who": "Diego", "parts": ["Deal. But we won’t swim unless the sea ", {"num": "8"}, {"gap": "be"}, " calm."]}, {"who": "Camila", "parts": ["Of course. If we ", {"num": "9"}, {"gap": "have"}, " time, we’ll take photos at sunset!"]}], "after": "Listen again and check. Then act it out with a partner and change the place: Jarabacoa, Samaná, Los Tres Ojos .", "ansT": {"1": "rains", "2": "will stay", "3": "leave", "4": "will miss", "5": "drives", "6": "won’t need", "7": "bring", "8": "is", "9": "have"}, "pairs": ["📱 your phone dies at school", "🎂 it rains on your birthday", "💰 you win 5,000 pesos", "✈️ your best friend moves away", "📉 you get a bad grade", "📶 the Wi-Fi stops working"], "sound": ["will → ’ll: I’ll · you’ll · we’ll · it’ll", "will not → won’t /woʊnt/ ≠ want /wɑːnt/", "Say it fast! If it’s hot, I’ll swim. If it rains, I won’t."], "rtitle": "Rainy Season Survival Guide", "rsub": "by Valeria, 15 — four tips for the wettest months of the year", "paras": ["Here in the Dominican Republic, the rainy season usually starts in May. The days are hot and sunny, and then, suddenly, the sky turns gray and it pours. If you live here, you know the routine! Here are my top tips.", "1. Check the forecast. If you check the weather app in the morning, you’ll know when to take an umbrella. Rain often comes in the afternoon, so plan your activities early.", "2. Protect your phone. If water gets into your phone, it will stop working. I always carry a plastic bag in my backpack. It’s cheap and it works!", "3. Stay away from flooded streets. Some streets flood in minutes. If you walk through the water, you won’t see holes or open drains, and that’s dangerous.", "4. Be ready for power cuts. Storms sometimes cut the electricity. If you charge your power bank every night, you won’t be in the dark.", "Rain isn’t all bad, though. The plants grow fast, the air feels fresh and the mangoes taste amazing!"], "pull": "“If you prepare a little, you’ll enjoy the rainy season too!”", "atitle": "A. Choose the best answer.", "qa": ["1. When does the rain often come? a) morning · b) afternoon · c) night", "2. Why does Valeria carry a plastic bag? a) for snacks · b) for her phone · c) for the beach", "3. Why are flooded streets dangerous? a) you can’t see holes · b) the water is cold"], "qb": ["4. The rainy season usually starts in May. ____", "5. Valeria’s power bank is new. ____", "6. Valeria thinks rain is all bad. ____"], "qc": "Underline four first conditional sentences in the text.", "ansR": {"1": "b", "2": "b", "3": "a", "4": "T", "5": "DS", "6": "F"}, "ansR_raw": "Answers 7: 1 b · 2 b · 3 a · 4 T · 5 DS · 6 F", "sub": "Real possibilities, plans, warnings and promises"}, {"n": 7, "title": "If I were…", "setting": "Daniela and Kevin are talking on the way home from school.", "lines": [{"who": "Daniela", "parts": ["Kevin, what ", {"num": "1"}, {"gap": "you / do"}, " if you won the school talent show?"]}, {"who": "Kevin", "parts": ["If I ", {"num": "2"}, {"gap": "win"}, ", I’d buy a new guitar!"]}, {"who": "Daniela", "parts": ["Cool. If I ", {"num": "3"}, {"gap": "be"}, " you, I’d enter the contest."]}, {"who": "Kevin", "parts": ["I know, but if I ", {"num": "4"}, {"gap": "sing"}, " in front of everybody, I’d be so nervous!"]}, {"who": "Daniela", "parts": ["If you ", {"num": "5"}, {"gap": "practice"}, " every day, you ", {"num": "6"}, {"gap": "not / be"}, " nervous."]}, {"who": "Kevin", "parts": ["Maybe you’re right. Would you help me if I ", {"num": "7"}, {"gap": "ask"}, " you?"]}], "after": "Listen again and check. Then give your partner advice with If I were you…", "ansT": {"1": "would you do", "2": "won", "3": "were", "4": "sang", "5": "practiced", "6": "wouldn’t be", "7": "asked"}, "pairs": ["🦸 you had a superpower", "💸 you found 10,000 pesos", "🏝️ you lived on an island", "👻 you saw a ghost", "🌎 you could speak every language", "🏫 you were the principal for a day"], "sound": ["I’d /aɪd/ · you’d /juːd/ · we’d /wiːd/", "Say it fast! If I were you, I’d try. I wouldn’t give up!"], "rtitle": "If I Were the President…", "rsub": "Four teens share what they would change", "paras": ["Our school magazine asked students one simple question: “If you were the president for one day, what would you do?” Here are some of the answers.", "Mía, 14: “If I were the president, I would plant trees in every street. The cities would be cooler and the air would be cleaner.”", "Joel, 15: “I’d give free Wi-Fi to every school in the country. If students had good internet, they could learn much more.”", "Fernanda, 14: “If I could change one thing, I’d protect the beaches. I’d stop people from leaving plastic on the sand.” Luis, 16: “Honestly? If I were the president, I’d be very nervous! But I’d listen to young people.”"], "pull": "“If students had good internet, they could learn much more.”", "atitle": "A. Who…?", "qa": ["1. wants cleaner beaches?", "2. talks about the internet?", "3. wants to plant trees?", "4. would be nervous?"], "qb": ["5. Mía thinks trees would make cities cooler. ____", "6. Joel has bad internet at home. ____", "7. Luis would listen to young people. ____"], "qc": "Underline four second conditional sentences. Which idea do you like best?", "ansR": {"1": "Fernanda", "2": "Joel", "3": "Mía", "4": "Luis", "5": "T", "6": "DS", "7": "T"}, "ansR_raw": "Answers 7: 1 Fernanda · 2 Joel · 3 Mía · 4 Luis · 5 T · 6 DS · 7 T", "sub": "Dreams, imaginary situations and advice"}, {"n": 8, "title": "If I had known…", "setting": "Rubén arrives at school very late. His friend Ana is waiting.", "lines": [{"who": "Ana", "parts": ["Rubén! The test started an hour ago. What happened?"]}, {"who": "Rubén", "parts": ["I missed the bus. If I ", {"num": "1"}, {"gap": "wake up"}, " earlier, I ", {"num": "2"}, {"gap": "not / miss"}, " it."]}, {"who": "Ana", "parts": ["You ", {"num": "3"}, {"gap": "should / set"}, " an alarm!"]}, {"who": "Rubén", "parts": ["I know. I ", {"num": "4"}, {"gap": "wish / go"}, " to bed earlier last night."]}, {"who": "Ana", "parts": ["If you ", {"num": "5"}, {"gap": "call"}, " me, my dad ", {"num": "6"}, {"gap": "drive"}, " you."]}, {"who": "Rubén", "parts": ["Really? I ", {"num": "7"}, {"gap": "should / ask"}, " you!"]}], "after": "Listen again and check. Then tell your partner about a time you were late.", "ansT": {"1": "had woken up", "2": "wouldn’t have missed", "3": "should have set", "4": "wish I had gone", "5": "had called", "6": "would have driven", "7": "should have asked"}, "pairs": ["📱 Your friend dropped your phone in the pool.", "🎂 You forgot your mom’s birthday.", "📝 You didn’t study and failed a test.", "🚌 You took the wrong bus.", "⚽ Your team lost the final.", "🍕 You ate your brother’s pizza."], "sound": ["In fast speech: would have → /ˈwʊdəv/ “woulda”", "Say it fast! I would’ve come · You should’ve told me!"], "rtitle": "The Worst Morning of My Life", "rsub": "A short story about one small mistake — and a big lesson", "paras": ["It was the day of the big English presentation, and everything went wrong. First, I forgot to charge my phone, so my alarm didn’t ring. If I had charged it, I would have woken up at six, not at seven thirty!", "I ran to the bus stop, but I had left my presentation on the kitchen table. I went back home to get it, and when I returned, the bus had gone.", "I walked to school in the rain without an umbrella. When I arrived, I was completely wet and twenty minutes late. My teacher, Miss Ramírez, just smiled and said, “You should have called the school.”", "In the end, I gave my presentation and got a B+. Not bad! But I learned my lesson. Now I charge my phone every night. I wish I had started doing it years ago!"], "pull": "“If I had charged it, I would have woken up at six.”", "atitle": "A. Answer the questions.", "qa": ["1. Why didn’t the alarm ring?", "2. What did the writer leave at home?", "3. How late was the writer?", "4. What grade did the writer get?"], "qb": ["5. The writer took the bus to school. ____", "6. Miss Ramírez was angry. ____", "7. The writer now charges the phone every night. ____"], "qc": "Underline three examples of the third conditional, wish or should have.", "ansR": {"1": "the phone wasn’t charged", "2": "the presentation", "3": "twenty minutes", "4": "B+", "5": "F", "6": "F", "7": "T"}, "ansR_raw": "Answers 7: 1 the phone wasn’t charged · 2 the presentation · 3 twenty minutes · 4 B+ · 5 F · 6 F · 7 T", "sub": "Regrets, mistakes and imaginary pasts"}, {"n": 9, "title": "What were you doing?", "setting": "Two friends talk about last night’s blackout.", "lines": [{"who": "Mariela", "parts": ["What ", {"num": "1"}, {"gap": "you / do"}, " when the lights went out?"]}, {"who": "Andrés", "parts": ["I ", {"num": "2"}, {"gap": "play"}, " a video game. I lost everything!"]}, {"who": "Mariela", "parts": ["Oh no! I ", {"num": "3"}, {"gap": "take"}, " a shower when it ", {"num": "4"}, {"gap": "happen"}, "."]}, {"who": "Andrés", "parts": ["In the dark? What did you do?"]}, {"who": "Mariela", "parts": ["While I ", {"num": "5"}, {"gap": "look"}, " for a towel, I ", {"num": "6"}, {"gap": "fall"}, " over the cat!"]}, {"who": "Andrés", "parts": ["Ha ha! Was your cat OK?"]}], "after": "Listen again and check. Then tell your partner your own blackout story.", "ansT": {"1": "were you doing", "2": "was playing", "3": "was taking", "4": "happened", "5": "was looking", "6": "fell"}, "pairs": ["🌅 at 7 a.m. today", "🍽️ at dinner time yesterday", "📺 at 9 p.m. last Saturday", "🎄 on Christmas Eve at midnight", "🏫 when the bell rang today", "⚡ during the last blackout"], "sound": ["In fast speech: was → /wəz/ · were → /wə/", "Say it fast! I /wəz/ sleeping · They /wə/ playing."], "rtitle": "The Night the Lights Went Out", "rsub": "One neighborhood, one blackout, and a lot of stories", "paras": ["Last summer, on a hot Tuesday night, the whole neighborhood of Villa Consuelo went dark. It was 8:30 p.m., and everybody was doing something different.", "Doña Rosa was cooking rice and beans when the lights went out. She lit a candle and kept cooking. “The rice was perfect!” she laughed. Next door, the Pérez kids were doing their homework while their dad was watching baseball.", "At first, people were angry. But then something special happened. While the neighbors were sitting outside to escape the heat, someone started playing a guitar. Soon everybody was singing bachata and laughing.", "When the lights came back at 11 p.m., nobody wanted to go inside. “We were having so much fun,” said Tomás, 15. “I think we need more blackouts!”"], "pull": "“While the neighbors were sitting outside, someone started playing a guitar.”", "atitle": "A. Answer the questions.", "qa": ["1. What time did the lights go out?", "2. What was Doña Rosa doing?", "3. What were the Pérez kids doing?", "4. What did the neighbors do outside?"], "qb": ["5. The blackout happened in winter. ____", "6. Doña Rosa’s rice was good. ____", "7. Tomás wants more blackouts. ____"], "qc": "Underline four examples of the past continuous.", "ansR": {"1": "at 8:30 p.m.", "2": "cooking rice and beans", "3": "their homework", "4": "sang and laughed", "5": "F", "6": "T", "7": "T"}, "ansR_raw": "Answers 7: 1 at 8:30 p.m. · 2 cooking rice and beans · 3 their homework · 4 sang and laughed · 5 F · 6 T · 7 T", "sub": "Telling stories: background actions and interruptions"}, {"n": 10, "title": "Before it happened", "setting": "Lucía arrives at the train station in Santo Domingo. She calls her friend Pablo.", "lines": [{"who": "Lucía", "parts": ["Pablo, I’m at the station, but it’s empty! Where is everybody?"]}, {"who": "Pablo", "parts": ["Oh no! The train ", {"num": "1"}, {"gap": "already / leave"}, ". We left at 10."]}, {"who": "Lucía", "parts": ["But I ", {"num": "2"}, {"gap": "check"}, " the time online! It said 10:30."]}, {"who": "Pablo", "parts": ["They ", {"num": "3"}, {"gap": "change"}, " the schedule last week."]}, {"who": "Lucía", "parts": ["I didn’t know! I ", {"num": "4"}, {"gap": "never / miss"}, " a train before."]}, {"who": "Pablo", "parts": ["Don’t worry. By the time you ", {"num": "5"}, {"gap": "arrive"}, ", we’ll be waiting at the next stop."]}], "after": "Listen again and check. Then tell your partner about a time you were too late.", "ansT": {"1": "had already left", "2": "had checked", "3": "had changed", "4": "had never missed", "5": "arrive"}, "pairs": ["😭 Ana was crying.", "🏆 Leo was very happy.", "🧹 The house was a mess.", "😴 Kevin was very tired.", "🍰 The cake was gone.", "🔑 Mom couldn’t open the door."], "sound": ["In fast speech: had → /əd/ and often just ’d", "Say it fast! I’d already eaten · She’d never seen it."], "rtitle": "The Lost Letter of 1930", "rsub": "A letter found in an old house tells a surprising story", "paras": ["Last year, the Martínez family bought an old house in Puerto Plata. While they were cleaning the attic, they found a small box. Inside, there was a yellow letter. Someone had written it in 1930.", "The letter was from a young man called Ernesto to a girl called Clara. Ernesto had moved to New York to work, and he had saved money for two years. He wanted Clara to join him.", "The family wanted to know what had happened to them. They asked the old neighbors. Finally, Doña Carmen, 94, remembered. “Clara never received that letter,” she said. “By the time it arrived, she had already left for New York to find him!”", "Did they ever meet? Nobody knows. But the Martínez family has kept the letter in a frame in the living room."], "pull": "“By the time it arrived, she had already left to find him!”", "atitle": "A. Answer the questions.", "qa": ["1. Where did the family find the letter?", "2. When had someone written it?", "3. Why had Ernesto moved to New York?", "4. Who remembered the story?"], "qb": ["5. Ernesto had saved money for two years. ____", "6. Clara received the letter. ____", "7. Ernesto and Clara got married. ____"], "qc": "Underline five verbs in the past perfect.", "ansR": {"1": "in the attic", "2": "in 1930", "3": "to work", "4": "Doña Carmen", "5": "T", "6": "F", "7": "DS"}, "ansR_raw": "Answers 8: 1 in the attic · 2 in 1930 · 3 to work · 4 Doña Carmen · 5 T · 6 F · 7 DS", "sub": "Putting past events in order"}, {"n": 11, "title": "Back then", "setting": "Camila is looking at old photos with her grandpa, Don Julio.", "lines": [{"who": "Camila", "parts": ["Abuelo, is that you? You ", {"num": "1"}, {"gap": "have"}, " so much hair!"]}, {"who": "Don Julio", "parts": ["Ha! Yes, and I ", {"num": "2"}, {"gap": "play"}, " baseball every day."]}, {"who": "Camila", "parts": [{"num": "3"}, {"gap": "you / have"}, " a TV at home?"]}, {"who": "Don Julio", "parts": ["No, we ", {"num": "4"}, {"gap": "not / have"}, " one. We ", {"num": "5"}, {"gap": "listen"}, " to the radio."]}, {"who": "Camila", "parts": ["Wow. And what about phones?"]}, {"who": "Don Julio", "parts": ["There ", {"num": "6"}, {"gap": "be"}, " only one phone in the whole street!"]}], "after": "Listen again and check. Then ask an older person about their childhood.", "ansT": {"1": "used to have", "2": "used to play", "3": "Did you use to have", "4": "didn’t use to have", "5": "used to listen", "6": "used to be"}, "pairs": ["🧸 have a favorite toy?", "📺 watch cartoons in the morning?", "🥦 like vegetables?", "🌙 be afraid of the dark?", "🏠 live in a different house?", "🎮 play the same games?"], "sound": ["used to sounds like /ˈjuːstə/ — “yoos-ta”, not “yoozd-too”", "Say it fast! I used to /ˈjuːstə/ live there."], "rtitle": "When My Mom Was Fifteen", "rsub": "A student interviews her mother about the 1990s", "paras": ["For a school project, Valeria, 14, interviewed her mother, Mónica, about her life as a teenager in Santiago in the 1990s.", "“We didn’t use to have smartphones,” Mónica explained. “If I wanted to talk to my friends, I used to call them on the house phone — and my brother used to listen to everything!”", "Music was different too. “We used to record songs from the radio onto cassettes. It took hours to make a good one!” On weekends, she and her friends used to meet at the park. “We didn’t use to text. We just went there and waited.”", "Is anything the same? “Yes,” Mónica laughed. “Teenagers still think their parents don’t understand anything!”"], "pull": "“We didn’t use to text. We just went there and waited.”", "atitle": "A. Answer the questions.", "qa": ["1. Where did Mónica live as a teenager?", "2. How did she use to call her friends?", "3. How did she use to get music?", "4. Where did she use to meet her friends?"], "qb": ["5. Mónica’s brother used to listen to her calls. ____", "6. Mónica used to have a cassette player in her car. ____", "7. Mónica thinks some things haven’t changed. ____"], "qc": "Underline five examples of used to / didn’t use to.", "ansR": {"1": "in Santiago", "2": "on the house phone", "3": "she recorded songs from the radio", "4": "at the park", "5": "T", "6": "DS", "7": "T"}, "ansR_raw": "Answers 7: 1 in Santiago · 2 on the house phone · 3 she recorded songs from the radio · 4 at the park · 5 T · 6 DS · 7 T", "sub": "Past habits and states that are not true anymore"}, {"n": 12, "title": "Wait for me!", "setting": "Nicole and Samuel are at the bus stop after school.", "lines": [{"who": "Nicole", "parts": ["Who are you waiting ", {"num": "1"}, {"gap": ""}, "?"]}, {"who": "Samuel", "parts": ["My brother. He’s looking ", {"num": "2"}, {"gap": ""}, " his keys again."]}, {"who": "Nicole", "parts": ["Ha! Hey, are you going to Ana’s party tonight?"]}, {"who": "Samuel", "parts": ["I’ll ", {"num": "3"}, {"gap": ""}, " go, but it depends ", {"num": "4"}, {"gap": ""}, " my mom."]}, {"who": "Nicole", "parts": ["Don’t worry ", {"num": "5"}, {"gap": ""}, " it. She’ll ", {"num": "6"}, {"gap": ""}, " say yes!"]}, {"who": "Samuel", "parts": ["I hope so. I agree ", {"num": "7"}, {"gap": ""}, " you — it’s going to be fun!"]}], "after": "Word box: for · for · probably · on · about · definitely · with", "ansT": {"1": "for", "2": "for", "3": "probably", "4": "on", "5": "about", "6": "definitely", "7": "with"}, "pairs": ["😟 What do you worry about?", "💭 What do you dream about?", "🎧 What music do you listen to?", "🐶 Who do you look after?", "🤝 Who do you agree with most?", "💰 What do you spend money on?"], "sound": ["Verbs and prepositions join together: wait_for /weɪtfə/ · look_after /lʊkɑːftə/", "Say it fast! What are you waiting_for?"], "rtitle": "Summers at Grandma’s House", "rsub": "Three teens remember the best moments of their childhood", "paras": ["We asked three teens: “What is your favorite childhood memory?” Here’s what they told us.", "Ana, 15: “Every summer, my family would go to my grandma’s house in Jarabacoa. She would wake us up early and we would pick oranges in the garden. I still dream about that place.”", "Rafael, 14: “My dad would take me to watch the Águilas play every Sunday. I would scream so much that I couldn’t talk on Monday! I’ll definitely take my own kids one day.”", "Sara, 16: “My older sister would look after me when my parents worked. She would read me stories and paint my nails. I didn’t agree with her about anything, but I loved her a lot.”"], "pull": "“I still dream about that place.”", "atitle": "A. Who…?", "qa": ["1. used to pick oranges?", "2. went to baseball games?", "3. was looked after by a sister?", "4. wants to repeat the memory with their children?"], "qb": ["5. Ana’s grandma lives in Jarabacoa. ____", "6. Rafael lost his voice on Mondays. ____", "7. Sara and her sister always agreed. ____"], "qc": "Underline four examples of would for past habits.", "ansR": {"1": "Ana", "2": "Rafael", "3": "Sara", "4": "Rafael", "5": "T", "6": "T", "7": "F"}, "ansR_raw": "Answers 7: 1 Ana · 2 Rafael · 3 Sara · 4 Rafael · 5 T · 6 T · 7 F", "sub": "Verbs with prepositions, childhood memories and how sure you are"}, {"n": 13, "title": "Rules and advice", "setting": "Gabriel is staying at his friend Luis’s house for the weekend. Luis’s mom explains the rules.", "lines": [{"who": "Mrs. Peña", "parts": ["Welcome, Gabriel! You ", {"num": "1"}, {"gap": ""}, " take off your shoes at the door."]}, {"who": "Gabriel", "parts": ["Sure. ", {"num": "2"}, {"gap": ""}, " I make my bed?"]}, {"who": "Mrs. Peña", "parts": ["No, you ", {"num": "3"}, {"gap": ""}, ". You’re our guest!"]}, {"who": "Luis", "parts": ["But we ", {"num": "4"}, {"gap": ""}, " play video games after 10 p.m."]}, {"who": "Mrs. Peña", "parts": ["That’s right. And you ", {"num": "5"}, {"gap": ""}, " go to bed early — you look tired!"]}, {"who": "Gabriel", "parts": ["Thank you, Mrs. Peña. You’re very kind."]}], "after": "Word box: have to · Do I have to · don’t have to · mustn’t · should", "ansT": {"1": "have to", "2": "Do I have to", "3": "don’t have to", "4": "mustn’t", "5": "should"}, "pairs": ["😴 I’m always tired.", "📱 I spend 8 hours on my phone.", "📉 I failed my math test.", "🤧 I have a terrible cold.", "😟 I had a fight with my friend.", "💸 I spend all my money."], "sound": ["have to → /ˈhæftə/ “haf-ta” · has to → /ˈhæstə/ “has-ta”", "Say it fast! I have to go · She has to study."], "rtitle": "Safe and Happy at the Beach", "rsub": "A lifeguard from Juan Dolio shares her top rules", "paras": ["Karla Mejía, 24, has been a lifeguard at Juan Dolio beach for five years. She sees hundreds of teenagers every weekend. Here are her top rules for a safe day at the beach.", "“First, you must always swim where you can see a lifeguard. When you see a red flag, you mustn’t go in the water — the waves are too dangerous.”", "“You should wear sunscreen and drink a lot of water, even when it’s cloudy. And you shouldn’t leave plastic on the sand. The turtles think it’s food!”", "“You don’t have to be a great swimmer to have fun,” she adds. “But you have to respect the ocean. It’s beautiful, but it’s stronger than all of us.”"], "pull": "“You don’t have to be a great swimmer to have fun.”", "atitle": "A. Answer the questions.", "qa": ["1. How long has Karla been a lifeguard?", "2. What does a red flag mean?", "3. Why shouldn’t you leave plastic on the sand?", "4. What do you have to respect?"], "qb": ["5. Karla works at Juan Dolio. ____", "6. You don’t need sunscreen on cloudy days. ____", "7. Karla saved a teenager last year. ____"], "qc": "Underline one example each of must, mustn’t, should and don’t have to.", "ansR": {"1": "five years", "2": "you mustn’t go in the water", "3": "turtles think it’s food", "4": "the ocean", "5": "T", "6": "F", "7": "DS"}, "ansR_raw": "Answers 8: 1 five years · 2 you mustn’t go in the water · 3 turtles think it’s food · 4 the ocean · 5 T · 6 F · 7 DS", "sub": "Obligations, prohibitions and good ideas"}, {"n": 14, "title": "I’ll be able to…", "setting": "It’s graduation day. Melissa talks to her cousin Daniel.", "lines": [{"who": "Daniel", "parts": ["Congratulations, Melissa! How do you feel?"]}, {"who": "Melissa", "parts": ["Amazing! I wasn’t sure I ", {"num": "1"}, {"gap": "finish"}, ", but I did it!"]}, {"who": "Daniel", "parts": ["What’s next? Will you ", {"num": "2"}, {"gap": "study"}, " in the capital?"]}, {"who": "Melissa", "parts": ["I hope so. I’ve ", {"num": "3"}, {"gap": "never / live"}, " alone before."]}, {"who": "Daniel", "parts": ["You ", {"num": "4"}, {"gap": "ought / talk"}, " to my sister. She lives there."]}, {"who": "Melissa", "parts": ["Great idea! I ", {"num": "5"}, {"gap": "must / call"}, " her tonight."]}], "after": "Listen again and check. Then talk about something you were able to do this year.", "ansT": {"1": "would be able to finish", "2": "be able to study", "3": "never been able to live", "4": "ought to talk", "5": "must call"}, "pairs": ["🏊 Have you ever been able to swim 1 km?", "🗣️ Will you be able to speak English well in 2 years?", "🎸 Would you like to be able to play an instrument?", "🧮 Were you able to finish your last test on time?", "🚗 When will you be able to drive?", "🍳 Are you able to cook a full meal?"], "sound": ["ought to → /ˈɔːtə/ “aw-ta”", "Say it fast! You ought to rest · We ought to go."], "rtitle": "She Couldn’t Swim. Now She’s a Champion.", "rsub": "The story of a 16-year-old swimmer from Barahona", "paras": ["When Yulissa Féliz was ten, she wasn’t able to swim at all. She lived in Barahona, near the sea, but she was afraid of the water. “My friends could swim, but I just watched from the sand,” she remembers.", "Everything changed when a coach opened a free swimming school near her home. “My mom said I ought to try. The first day, I cried. But after two months, I was able to swim across the pool!”", "Now, at sixteen, Yulissa has won three national medals. She trains every morning at 5 a.m. “I have to wake up very early, but I love it,” she says.", "Her next goal? The Central American Games. “I hope I’ll be able to win a medal for my country. And I’d like to be able to teach other kids, too.”"], "pull": "“After two months, I was able to swim across the pool!”", "atitle": "A. Answer the questions.", "qa": ["1. Why didn’t Yulissa swim when she was ten?", "2. Who told her to try?", "3. How many national medals has she won?", "4. What would she like to do in the future?"], "qb": ["5. Yulissa grew up in Barahona. ____", "6. The swimming school was very expensive. ____", "7. Yulissa trains in the afternoon. ____"], "qc": "Underline four forms of be able to in the text.", "ansR": {"1": "she was afraid of the water", "2": "her mom", "3": "three", "4": "teach other kids", "5": "T", "6": "F", "7": "F"}, "ansR_raw": "Answers 7: 1 she was afraid of the water · 2 her mom · 3 three · 4 teach other kids · 5 T · 6 F · 7 F", "sub": "Abilities in different times, and what’s right to do"}, {"n": 15, "title": "It must be…", "setting": "Two friends hear a strange noise at night during a sleepover.", "lines": [{"who": "Paula", "parts": ["Did you hear that? Someone ", {"num": "1"}, {"gap": ""}, " be in the kitchen!"]}, {"who": "Kenia", "parts": ["It ", {"num": "2"}, {"gap": ""}, " be a person. The doors are locked."]}, {"who": "Paula", "parts": ["Then what is it? It ", {"num": "3"}, {"gap": ""}, " be a ghost…"]}, {"who": "Kenia", "parts": ["Or it ", {"num": "4"}, {"gap": ""}, " be the cat. She’s always hungry."]}, {"who": "Paula", "parts": ["Look, the fridge is open. It ", {"num": "5"}, {"gap": ""}, " be your brother!"]}, {"who": "Kenia", "parts": ["Ha! You’re right. It’s definitely Marcos eating ice cream."]}], "after": "Word box: must · can’t · might · could · must", "ansT": {"1": "must", "2": "can’t", "3": "might", "4": "could", "5": "must"}, "pairs": ["📦 a box that is moving", "🔊 a loud noise at 3 a.m.", "🌧️ wet footprints on the floor", "📱 25 missed calls from Mom", "🍰 chocolate on your brother’s face", "🚓 a police car outside your house"], "sound": ["In deductions, we stress the modal: She MUST be tired · It CAN’T be true!", "Say it with feeling! That CAN’T be right!"], "rtitle": "The Mystery of the Missing Trophy", "rsub": "Who took the school’s baseball trophy? You decide!", "paras": ["On Monday morning, the school’s baseball trophy was gone. It had been on a shelf in the main hall since the team won the championship. The principal asked the students to help find it.", "There were three clues. First, there was a footprint with mud on the floor. Second, someone had left a red cap near the shelf. Third, the window was open, but it was on the second floor.", "“It can’t be someone from outside,” said Andrea, 15. “Nobody could climb to the second floor.” Her friend José agreed. “And the red cap might be from the baseball team — their caps are red!”", "In the end, the coach laughed and solved the mystery. “I took it to clean it for the photo!” he said. “The muddy footprint must be mine — I was at practice all weekend.”"], "pull": "“It can’t be someone from outside.”", "atitle": "A. Answer the questions.", "qa": ["1. Where was the trophy?", "2. What were the three clues?", "3. Why did Andrea think it couldn’t be someone from outside?", "4. Who took the trophy, and why?"], "qb": ["5. The window was on the first floor. ____", "6. The baseball team wears red caps. ____", "7. The coach was angry with the students. ____"], "qc": "Underline four modals of deduction in the text.", "ansR": {"1": "on a shelf in the main hall", "2": "a muddy footprint, a red cap, an open window", "3": "nobody could climb to the second floor", "4": "the coach, to clean it", "5": "F", "6": "T", "7": "F"}, "ansR_raw": "Answers 7: 1 on a shelf in the main hall · 2 a muddy footprint, a red cap, an open window · 3 nobody could climb to the second floor · 4 the coach, to clean it · 5 F · 6 T · 7 F", "sub": "Making deductions like a detective"}, {"n": 16, "title": "It was made in…", "setting": "A class visits a cocoa farm in San Francisco de Macorís. The guide explains.", "lines": [{"who": "Guide", "parts": ["Welcome! This farm ", {"num": "1"}, {"gap": "start"}, " by my grandfather in 1960."]}, {"who": "Student", "parts": ["Wow! How is chocolate ", {"num": "2"}, {"gap": "make"}, "?"]}, {"who": "Guide", "parts": ["First, the cocoa pods ", {"num": "3"}, {"gap": "cut"}, " from the trees by hand."]}, {"who": "Student", "parts": ["And then?"]}, {"who": "Guide", "parts": ["The beans ", {"num": "4"}, {"gap": "dry"}, " in the sun for a week."]}, {"who": "Student", "parts": ["Where is the chocolate ", {"num": "5"}, {"gap": "sell"}, "?"]}, {"who": "Guide", "parts": ["It ", {"num": "6"}, {"gap": "export"}, " to Europe. Last year, 20 tons were sold!"]}], "after": "Listen again and check. Then explain how something is made to your partner.", "ansT": {"1": "was started", "2": "made", "3": "are cut", "4": "are dried", "5": "sold", "6": "is exported"}, "pairs": ["📞 Who was the telephone invented by?", "💎 Where is larimar found?", "🏟️ When was the Estadio Quisqueya built?", "🍌 Where are bananas grown in RD?", "🎵 Who was “Ojalá que llueva café” sung by?", "⛪ When was the first cathedral built?"], "sound": ["In passives, was and were are weak: /wəz/ /wə/", "Say it fast! It /wəz/ made in Santiago."], "rtitle": "From the Mountain to Your Cup", "rsub": "How coffee is grown and made in Jarabacoa", "paras": ["Every morning, millions of cups of coffee are drunk around the world. But how is coffee made? We visited a family farm in Jarabacoa to find out.", "Coffee plants are grown in the mountains, where it is cool and rainy. When the red fruits are ready, they are picked by hand — usually between October and February. “Every fruit is chosen carefully,” explains Don Manuel, 62.", "Next, the fruits are washed and the beans are dried in the sun. After that, they are roasted in big machines. The smell is amazing! Finally, the coffee is packed and sent to shops all over the country.", "Coffee was first brought to the island in the 18th century. Today, Dominican coffee is sold in many countries and is known for its smooth taste."], "pull": "“Every fruit is chosen carefully.”", "atitle": "A. Put the steps in order (1–4).", "qa": ["1. The beans are roasted.", "2. The fruits are picked by hand.", "3. The coffee is packed.", "4. The beans are dried in the sun."], "qb": ["5. Coffee is grown in hot places by the sea. ____", "6. Coffee was brought to the island in the 1900s. ____", "7. Don Manuel’s grandchildren help on the farm. ____"], "qc": "Underline six passive verbs in the text.", "ansR": {"1": "3", "2": "1", "3": "4", "4": "2", "5": "F", "6": "F", "7": "DS"}, "ansR_raw": "Answers 7: order: 3 · 1 · 4 · 2 · 5 F · 6 F · 7 DS", "sub": "How things are made, grown and discovered"}, {"n": 17, "title": "It had been raining…", "setting": "Jonathan arrives at school completely wet. His friend Karen asks what happened.", "lines": [{"who": "Karen", "parts": ["Jonathan! Why are you so wet?"]}, {"who": "Jonathan", "parts": ["I ", {"num": "1"}, {"gap": "wait"}, " for the bus for 30 minutes in the rain!"]}, {"who": "Karen", "parts": ["Oh no! Hadn’t you checked the weather?"]}, {"who": "Jonathan", "parts": ["No. It ", {"num": "2"}, {"gap": "not / rain"}, " when I left home."]}, {"who": "Karen", "parts": ["Well, the streets near the school ", {"num": "3"}, {"gap": "close"}, " because of the flood."]}, {"who": "Jonathan", "parts": ["I know! The buses ", {"num": "4"}, {"gap": "send"}, " on a different route."]}], "after": "Listen again and check. Then tell your partner about a terrible rainy day.", "ansT": {"1": "had been waiting", "2": "hadn’t been raining", "3": "have been closed", "4": "were sent"}, "pairs": ["😴 Why were you so tired yesterday?", "🤒 Why was your voice so weak?", "🍝 Why was the kitchen a mess?", "😂 Why were your friends laughing?", "💦 Why were you so sweaty?", "📵 Why was your phone dead?"], "sound": ["In fast speech: had been → /əd bɪn/ “’d-bin”", "Say it fast! I’d been waiting · She’d been crying."], "rtitle": "After the Storm, the Cleanup", "rsub": "How a group of students turned trash into a project", "paras": ["Last October, a tropical storm hit Santo Domingo. It had been raining for three days, and many streets were full of water — and full of plastic bottles.", "A group of students from Liceo Juan Pablo Duarte decided to act. They had been learning about recycling in science class, so they organized a cleanup. More than 2,000 bottles were collected in one weekend!", "But that was only the beginning. The bottles were cleaned and cut, and they were used to build a vertical garden at the school. Now, vegetables are grown there and are given to the school cafeteria.", "The project has been copied by five other schools. “Next year, more gardens will be built,” says Laura, 16, one of the organizers. “Trash can be a treasure!”"], "pull": "“Trash can be a treasure!”", "atitle": "A. Answer the questions.", "qa": ["1. How long had it been raining?", "2. What had the students been learning?", "3. How many bottles were collected?", "4. What was built with the bottles?"], "qb": ["5. The storm happened in October. ____", "6. The vegetables are sold in a supermarket. ____", "7. Laura wants to study biology. ____"], "qc": "Underline one past perfect continuous and three passive verbs.", "ansR": {"1": "for three days", "2": "about recycling", "3": "more than 2,000", "4": "a vertical garden", "5": "T", "6": "F", "7": "DS"}, "ansR_raw": "Answers 8: 1 for three days · 2 about recycling · 3 more than 2,000 · 4 a vertical garden · 5 T · 6 F · 7 DS", "sub": "Long actions before a past moment, and more passives"}, {"n": 18, "title": "I had my hair cut", "setting": "Miguel is at the barbershop. He talks to Don Ramón, the barber.", "lines": [{"who": "Don Ramón", "parts": ["Hi, Miguel! What do you want today?"]}, {"who": "Miguel", "parts": ["I want to ", {"num": "1"}, {"gap": "my hair / cut"}, " short on the sides."]}, {"who": "Don Ramón", "parts": ["No problem. Big event?"]}, {"who": "Miguel", "parts": ["Yes! I’m ", {"num": "2"}, {"gap": "my photo / take"}, " for my school ID tomorrow."]}, {"who": "Don Ramón", "parts": ["Does your mom ", {"num": "3"}, {"gap": "let / you / choose"}, " your style?"]}, {"who": "Miguel", "parts": ["Yes, but she ", {"num": "4"}, {"gap": "make / me / keep"}, " it neat for school."]}], "after": "Listen again and check. Then role-play: one person is the barber or hairdresser.", "ansT": {"1": "have my hair cut", "2": "having my photo taken", "3": "let you choose", "4": "makes me keep"}, "pairs": ["💈 Where do you get your hair cut?", "📱 Have you ever had your phone fixed?", "👕 Who washes your clothes?", "📸 When did you last have your photo taken?", "🦷 How often do you have your teeth checked?", "🚲 Have you ever had your bike repaired?"], "sound": ["cut /kʌt/ · done /dʌn/ · fixed /fɪkst/ · washed /wɒʃt/", "Say it fast! I got my phone fixed /fɪkst/."], "rtitle": "The Teen Who Fixes Phones", "rsub": "A 16-year-old from Santiago started his own repair business", "paras": ["Two years ago, Kelvin Rosario, 16, dropped his phone and broke the screen. He couldn’t pay to have it fixed, so he watched videos online and repaired it himself.", "Soon, his friends started asking him for help. “At first, I fixed my cousins’ phones for free,” he says. “Then people started paying me.” Today, Kelvin has his own small business in Santiago.", "His parents let him work on weekends, but they make him finish his homework first. “School is the most important thing,” says his mother. Kelvin agrees: he wants to study engineering.", "Customers love his service. “I had my screen changed in only one hour,” says one happy client. “And it was much cheaper than at the mall!”"], "pull": "“I had my screen changed in only one hour.”", "atitle": "A. Answer the questions.", "qa": ["1. Why did Kelvin repair his own phone?", "2. How did he learn?", "3. When do his parents let him work?", "4. What do his parents make him do first?"], "qb": ["5. Kelvin’s business is in Santiago. ____", "6. Kelvin charges his cousins a lot of money. ____", "7. Kelvin wants to study engineering. ____"], "qc": "Underline two examples of have something done and one of make or let.", "ansR": {"1": "he couldn’t pay to have it fixed", "2": "by watching videos online", "3": "on weekends", "4": "finish his homework", "5": "T", "6": "F", "7": "T"}, "ansR_raw": "Answers 7: 1 he couldn’t pay to have it fixed · 2 by watching videos online · 3 on weekends · 4 finish his homework · 5 T · 6 F · 7 T", "sub": "Services, permissions and obligations"}, {"n": 19, "title": "The place where…", "setting": "Three friends visit the Museo de Historia Natural on a school trip.", "lines": [{"who": "Ana", "parts": ["Look at that skeleton! Is that the whale ", {"num": "1"}, {"gap": ""}, " was found in Samaná?"]}, {"who": "Pedro", "parts": ["Yes! And this is the room ", {"num": "2"}, {"gap": ""}, " they keep the dinosaur bones."]}, {"who": "Kevin", "parts": ["Who’s the woman ", {"num": "3"}, {"gap": ""}, " photo is on the wall?"]}, {"who": "Ana", "parts": ["She’s the scientist ", {"num": "4"}, {"gap": ""}, " discovered the fossil."]}, {"who": "Pedro", "parts": ["Cool! Hey, is there a shop ", {"num": "5"}, {"gap": ""}, " sells souvenirs?"]}, {"who": "Kevin", "parts": ["Yes, next to the café ", {"num": "6"}, {"gap": ""}, " we had lunch."]}], "after": "Word box: who · which · where · whose · that · where", "ansT": {"1": "which / that", "2": "where", "3": "whose", "4": "who / that", "5": "which / that", "6": "where"}, "pairs": ["🏝️ What’s a place where you want to go on vacation?", "🎤 Who is a singer whose songs you love?", "📺 What’s a series which everyone should watch?", "👨‍🏫 Who is a teacher who helped you a lot?", "🍲 What’s a food which reminds you of home?", "🏠 What’s a place where you can relax?"], "sound": ["With commas, we pause : My sister | who lives in Miami | is a nurse.", "Say it with pauses! Samaná | which is in the north | is beautiful."], "rtitle": "The Island Where the Whales Sing", "rsub": "The bay that thousands of whales visit every winter", "paras": ["Every January, something amazing happens in Samaná, a peninsula which is in the northeast of the Dominican Republic. Thousands of humpback whales, which travel from the cold North Atlantic, arrive in the warm waters of the bay.", "Why do they come? Samaná Bay is a place where the water is calm and warm, so it is perfect for the babies. The mothers, whose calves are born here, stay for about three months.", "Visitors who want to see the whales can take a boat tour. The guides, who are trained by experts, must keep the boats at a safe distance. “The best moment is when a whale jumps out of the water,” says Rosa, a guide who has worked here for ten years.", "Samaná is also famous for Cayo Levantado, a small island where you can swim on white beaches, and El Limón, a waterfall that is 40 meters high."], "pull": "“The best moment is when a whale jumps out of the water.”", "atitle": "A. Answer the questions.", "qa": ["1. Where do the whales come from?", "2. Why is Samaná Bay perfect for baby whales?", "3. Who trains the guides?", "4. What can you do on Cayo Levantado?"], "qb": ["5. The whales arrive in January. ____", "6. Rosa has been a guide for five years. ____", "7. Visitors can swim with the whales. ____"], "qc": "Underline five relative pronouns in the text.", "ansR": {"1": "the North Atlantic", "2": "the water is calm and warm", "3": "experts", "4": "swim on white beaches", "5": "T", "6": "F", "7": "DS"}, "ansR_raw": "Answers 8: 1 the North Atlantic · 2 the water is calm and warm · 3 experts · 4 swim on white beaches · 5 T · 6 F · 7 DS", "sub": "Giving more information about people, things and places"}, {"n": 20, "title": "She said that…", "setting": "Carla missed the class group chat. Her friend Julio tells her what everyone wrote.", "lines": [{"who": "Carla", "parts": ["What happened in the group chat? I had no battery!"]}, {"who": "Julio", "parts": ["Well, Miss Peña said the trip ", {"num": "1"}, {"gap": "be / cancel"}, "."]}, {"who": "Carla", "parts": ["What? Why?"]}, {"who": "Julio", "parts": ["She told us it ", {"num": "2"}, {"gap": "rain"}, " all week in Jarabacoa."]}, {"who": "Carla", "parts": ["Oh no! Did she say when we ", {"num": "3"}, {"gap": "go"}, " instead?"]}, {"who": "Julio", "parts": ["She said she ", {"num": "4"}, {"gap": "tell"}, " us the next day. And she promised ", {"num": "5"}, {"gap": "find"}, " a new date!"]}], "after": "Listen again and check. Then tell your partner some news you heard this week.", "ansT": {"1": "had been cancelled / was cancelled", "2": "had been raining / was raining", "3": "would go", "4": "would tell", "5": "to find"}, "pairs": ["😤 What can’t you stand doing?", "🙈 What do you avoid eating?", "🤞 What have you promised to do this month?", "🗓️ What are you planning to do this summer?", "😢 What do you miss doing from your childhood?", "🙅 What would you refuse to do for money?"], "sound": ["said /sed/ (not “say-ed”!) · told /təʊld/", "Say it fast! She told me /təʊld miː/ she was busy."], "rtitle": "Did You Hear What She Said?", "rsub": "How a simple message became a big school rumor", "paras": ["On a Monday morning, Marta told her friend Diego that she was feeling sick and that she might stay home the next day. Diego told Luis that Marta was very sick. Luis told the class that Marta had gone to the hospital!", "By lunchtime, everyone was talking about it. Some students said they had seen an ambulance. Others said Marta was going to miss the rest of the year. Someone even posted a sad message online.", "The next day, Marta arrived at school with a small cold — and a lot of messages on her phone. “I couldn’t stop laughing,” she said. “But I also felt a bit scared. People had believed something that wasn’t true.”", "Her teacher used the story in class. She told the students to check information before sharing it. “Rumors are like fire,” she said. “They are easy to start and very hard to stop.”"], "pull": "“Rumors are like fire.”", "atitle": "A. Answer the questions.", "qa": ["1. What did Marta tell Diego?", "2. What did Luis tell the class?", "3. How did Marta feel when she saw the messages?", "4. What did the teacher tell the students to do?"], "qb": ["5. Marta went to the hospital. ____", "6. Someone posted a message online. ____", "7. Diego apologized to Marta. ____"], "qc": "Underline four examples of reported speech in the text.", "ansR": {"1": "she was feeling sick and might stay home", "2": "Marta had gone to the hospital", "3": "she laughed but felt a bit scared", "4": "check information before sharing it", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 8: 1 she was feeling sick and might stay home · 2 Marta had gone to the hospital · 3 she laughed but felt a bit scared · 4 check information before sharing it · 5 F · 6 T · 7 DS", "sub": "Reporting what people say, and verb patterns"}, {"n": 21, "title": "She asked me…", "setting": "Camila had an interview for a summer volunteer program. Her friend Tomás wants to know everything.", "lines": [{"who": "Tomás", "parts": ["So? How was the interview?"]}, {"who": "Camila", "parts": ["Good, I think! First they asked me ", {"num": "1"}, {"gap": "why / want"}, " to volunteer."]}, {"who": "Tomás", "parts": ["Anything difficult?"]}, {"who": "Camila", "parts": ["Yes! They asked ", {"num": "2"}, {"gap": "if / have"}, " any experience and ", {"num": "3"}, {"gap": "what / be"}, " my biggest weakness!"]}, {"who": "Tomás", "parts": ["Wow. And at the end?"]}, {"who": "Camila", "parts": ["They told me ", {"num": "4"}, {"gap": "wait"}, " for an email and asked me ", {"num": "5"}, {"gap": "not / be"}, " late on the first day!"]}], "after": "Listen again and check. Then role-play an interview with your partner.", "ansT": {"1": "why I wanted", "2": "if I had", "3": "what my biggest weakness was", "4": "to wait", "5": "not to be"}, "pairs": ["👩 something your mom asked you to do this week", "👨‍🏫 something a teacher told you to do", "📱 a question a friend asked you yesterday", "🛑 something someone told you not to do", "👵 a question your grandparents always ask you", "🩺 a question a doctor asked you"], "sound": ["Direct questions go up ↗ · Reported questions go down ↘", "Compare! “Are you ready?” ↗ · He asked if I was ready. ↘"], "rtitle": "“They Asked Me If I Was Ready”", "rsub": "A 17-year-old tells us about her first job interview", "paras": ["Last summer, Gabriela Peña, 17, applied for her first job at an ice cream shop in Puerto Plata. “I was so nervous that my hands were shaking,” she remembers.", "“The manager asked me why I wanted to work there. I told her I loved ice cream — everyone laughed! Then she asked if I could work on weekends and whether I had ever used a cash register.”", "“The hardest moment was when she asked me what I would do with an angry customer. I said I would listen, stay calm and try to help.” At the end, the manager told her to come back the next Monday.", "Gabriela got the job. Her advice for other teens? “Before an interview, ask a friend to practice with you. And don’t forget to smile!”"], "pull": "“Don’t forget to smile!”", "atitle": "A. Answer the questions.", "qa": ["1. Where did Gabriela apply for a job?", "2. Why did everyone laugh?", "3. What was the hardest question?", "4. What does Gabriela tell other teens to do?"], "qb": ["5. Gabriela felt very relaxed. ____", "6. The manager asked if she could work on weekends. ____", "7. Gabriela works there every day now. ____"], "qc": "Underline four reported questions in the text.", "ansR": {"1": "at an ice cream shop in Puerto Plata", "2": "she said she loved ice cream", "3": "what she would do with an angry customer", "4": "practice with a friend and smile", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 at an ice cream shop in Puerto Plata · 2 she said she loved ice cream · 3 what she would do with an angry customer · 4 practice with a friend and smile · 5 F · 6 T · 7 DS", "sub": "Reporting questions, requests and orders"}, {"n": 22, "title": "Could you tell me…?", "setting": "Valeria calls Campamento Juvenil Jarabacoa. Ms. Ruiz answers the phone.", "lines": [{"who": "Ms. Ruiz", "parts": ["Good morning, Campamento Juvenil. How can I help you?"]}, {"who": "Valeria", "parts": ["Hi! Could you tell me ", {"num": "1"}, {"gap": "when / the camp / start"}, "?"]}, {"who": "Ms. Ruiz", "parts": ["Of course. It starts on July 1st and finishes on July 15th."]}, {"who": "Valeria", "parts": ["Great. Do you know ", {"num": "2"}, {"gap": "if / there / be"}, " a swimming pool?"]}, {"who": "Ms. Ruiz", "parts": ["Yes, there is. And there’s a river too!"]}, {"who": "Valeria", "parts": ["Cool! I’d like to know ", {"num": "3"}, {"gap": "how much / it / cost"}, "."]}, {"who": "Ms. Ruiz", "parts": ["It’s 15,000 pesos. I’ll send you the form as soon as you ", {"num": "4"}, {"gap": "give"}, " me your email."]}], "after": "Listen again and check. Then role-play a phone call to a club, gym or language school.", "ansT": {"1": "when the camp starts", "2": "if there is", "3": "how much it costs", "4": "give"}, "pairs": ["🏠 What will you do when you get home today?", "🎓 Where will you live after you finish school?", "💰 What will you buy as soon as you have money?", "🌧️ What will you do if it rains this weekend?", "🧳 Where will you go when you have a vacation?", "🎂 What will you do before your next birthday?"], "sound": ["Start high and friendly: Could you tell me… ↗", "Say it politely! Excuse me, do you know if the library is open?"], "rtitle": "Summer Camp: Learn, Lead, Play!", "rsub": "Two weeks of adventure in the mountains of Jarabacoa", "paras": ["Are you between 13 and 17? Do you love nature, sports and making new friends? Then Campamento Juvenil Jarabacoa is the place for you! Every July, 120 teens from all over the country spend two weeks in the mountains.", "What will you do? In the morning, you’ll take workshops in leadership, English and photography. After lunch, you can go hiking, rafting or play volleyball. At night, there are campfires, talent shows and movie nights.", "Many parents want to know if the camp is safe. All our counselors are trained in first aid, and there is a nurse on site 24 hours a day. Phones are allowed only from 7 to 8 p.m.", "Do you want to join? Fill in the online form before May 30th. As soon as we receive it, we’ll send you a welcome pack. We can’t wait to meet you!"], "pull": "“We can’t wait to meet you!”", "atitle": "A. Answer the questions.", "qa": ["1. How old do you need to be to join?", "2. What workshops can you take?", "3. When can campers use their phones?", "4. What will happen as soon as they receive your form?"], "qb": ["5. The camp lasts one month. ____", "6. There is a nurse at the camp. ____", "7. The camp is free. ____"], "qc": "Underline one indirect question and two future time clauses.", "ansR": {"1": "13 to 17", "2": "leadership, English, photography", "3": "from 7 to 8 p.m.", "4": "they’ll send a welcome pack", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 13 to 17 · 2 leadership, English, photography · 3 from 7 to 8 p.m. · 4 they’ll send a welcome pack · 5 F · 6 T · 7 DS", "sub": "Polite questions and talking about the future"}, {"n": 23, "title": "Although it was raining…", "setting": "Three friends come out of the cinema after watching a new superhero movie.", "lines": [{"who": "Nicole", "parts": ["Wow! That was ", {"num": "1"}, {"gap": ""}, " an amazing movie!"]}, {"who": "Andrés", "parts": ["Really? ", {"num": "2"}, {"gap": ""}, " the special effects were great, the story was boring."]}, {"who": "Raúl", "parts": ["I agree. And it was ", {"num": "3"}, {"gap": ""}, " long that I almost fell asleep!"]}, {"who": "Nicole", "parts": ["Come on! ", {"num": "4"}, {"gap": ""}, " the long story, the ending was fantastic."]}, {"who": "Andrés", "parts": ["OK, the ending was good. ", {"num": "5"}, {"gap": ""}, ", I prefer the first movie."]}, {"who": "Raúl", "parts": ["Me too. But the popcorn was ", {"num": "6"}, {"gap": ""}, " good! 🍿"]}], "after": "Word box: such · Although · so · Despite · However · so", "ansT": {"1": "such", "2": "Although", "3": "so", "4": "Despite", "5": "However", "6": "so"}, "pairs": ["🏙️ living in a big city", "📱 social media", "🏫 school uniforms", "🐶 having a pet", "🎮 video games", "🏖️ vacations at the beach"], "sound": ["We stress so and such to show strong feelings: It was SO funny!", "Say it with feeling! She’s SUCH a good singer!"], "rtitle": "Mud, Rain and a Perfect Goal", "rsub": "How the Liceo team won the final against all odds", "paras": ["Last Saturday, the Liceo Las Américas soccer team played the final of the school league. Although the sky was dark all morning, nobody wanted to cancel the game.", "Ten minutes after kickoff, it started to rain. The field was so muddy that the players kept falling. However, the fans didn’t go home. They stayed under umbrellas and kept singing.", "Despite playing with one player less, Las Américas defended well. At half-time, the score was 0–0. The coach, Mrs. Tavárez, told the team: “You are such strong players. Don’t give up!”", "In the last minute, the captain, Joel, kicked the ball from 30 meters. It flew over the goalkeeper and into the net. It was such a beautiful goal that even the other team clapped!"], "pull": "“It was such a beautiful goal that even the other team clapped!”", "atitle": "A. Answer the questions.", "qa": ["1. Why was it difficult to play?", "2. What did the fans do?", "3. What did the coach tell the team?", "4. How did Joel score?"], "qb": ["5. The game was cancelled because of the rain. ____", "6. Las Américas played with one player less. ____", "7. Joel is fifteen years old. ____"], "qc": "Underline two contrast linkers, one “so… that” and one “such… that”.", "ansR": {"1": "it was raining and the field was muddy", "2": "stayed and kept singing", "3": "they were strong and shouldn’t give up", "4": "he kicked it from 30 meters", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 8: 1 it was raining and the field was muddy · 2 stayed and kept singing · 3 they were strong and shouldn’t give up · 4 he kicked it from 30 meters · 5 F · 6 T · 7 DS", "sub": "Contrast, result and strong reactions"}, {"n": 24, "title": "Building words", "setting": "Students are preparing the school recycling fair. Lucía and Mateo check the to-do list.", "lines": [{"who": "Lucía", "parts": ["OK! Have we ", {"num": "1"}, {"gap": "make / do"}, " the posters yet?"]}, {"who": "Mateo", "parts": ["Yes, they’re ready. They look really ", {"num": "2"}, {"gap": "COLOR"}, "!"]}, {"who": "Lucía", "parts": ["Great. Who’s going to ", {"num": "3"}, {"gap": "make / do"}, " the shopping for the snacks?"]}, {"who": "Mateo", "parts": ["Me. And I’ll bring ", {"num": "4"}, {"gap": "USE"}, " bottles, not plastic ones."]}, {"who": "Lucía", "parts": ["Perfect. Oh no, I ", {"num": "5"}, {"gap": "SPELL"}, " “environment” on the banner!"]}, {"who": "Mateo", "parts": ["Don’t worry. ", {"num": "6"}, {"gap": "MAKE"}, " mistakes is normal. We can fix it!"]}], "after": "Complete with make / do or a form of the word in CAPITALS. Then listen and check.", "ansT": {"1": "made", "2": "colorful", "3": "do", "4": "reusable", "5": "misspelled", "6": "Making"}, "pairs": ["🧹 What chores do you do at home?", "🎥 Have you ever made a video?", "🏋️ What sport or exercise do you do?", "🤝 How do you make new friends?", "💵 How would you like to make money?", "🧪 Have you done a science project this year?"], "sound": ["Stress can move: PHO to · pho TOG rapher · photo GRAPH ic", "Say it! CRE ate? No: cre ATE · cre A tive · crea TIV ity"], "rtitle": "Old Clothes, New Ideas", "rsub": "A teen from La Romana turns old jeans into cool bags", "paras": ["Millions of clothes are thrown away every year. But Nayeli Castillo, 16, from La Romana, had a creative idea: why not give them a second life?", "It started when her favorite jeans got a hole. “They were useless as jeans, but the fabric was still beautiful,” she says. So she cut them and made a small bag. Her friends loved it.", "Now Nayeli makes bags, pencil cases and phone covers from old jeans. Her products are washable, comfortable and completely unique. “Upcycling is not just recycling,” she explains. “It means making something better than before.”", "Nayeli does all the work at home after school. Selling her products online has helped her save money for university. Her advice? “Be careful what you throw away. It could be your next big idea!”"], "pull": "“It could be your next big idea!”", "atitle": "A. Answer the questions.", "qa": ["1. Where is Nayeli from?", "2. How did her business start?", "3. What does she make from old jeans?", "4. What is the difference between upcycling and recycling?"], "qb": ["5. Nayeli’s products are all the same. ____", "6. She works on her products after school. ____", "7. Nayeli wants to study fashion. ____"], "qc": "Find six words with a prefix or suffix in the text.", "ansR": {"1": "La Romana", "2": "her favorite jeans got a hole", "3": "bags, pencil cases, phone covers", "4": "upcycling makes it better than before", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 La Romana · 2 her favorite jeans got a hole · 3 bags, pencil cases, phone covers · 4 upcycling makes it better than before · 5 F · 6 T · 7 DS", "sub": "Prefixes, suffixes, make & do"}, {"n": 25, "title": "Never give up!", "setting": "The class is organizing an end-of-year party. Sofía and Bryan make a plan.", "lines": [{"who": "Sofía", "parts": ["We need to ", {"num": "1"}, {"gap": ""}, " the party! Only one week left."]}, {"who": "Bryan", "parts": ["I know. Let’s not ", {"num": "2"}, {"gap": ""}, " it any longer."]}, {"who": "Sofía", "parts": ["Who can ", {"num": "3"}, {"gap": ""}, " the cake from the bakery?"]}, {"who": "Bryan", "parts": ["My dad can. Hey, did you ", {"num": "4"}, {"gap": ""}, " a theme yet?"]}, {"who": "Sofía", "parts": ["Yes! “Our Adventure”. We’ll show photos from the whole year."]}, {"who": "Bryan", "parts": ["Perfect. Just don’t ", {"num": "5"}, {"gap": ""}, " ice — last year we had warm sodas!"]}], "after": "Word box: set up · put off · pick up · come up with · run out of", "ansT": {"1": "set up", "2": "put off", "3": "pick up", "4": "come up with", "5": "run out of"}, "pairs": ["💡 What’s the best idea you came up with this year?", "😓 What difficult moment did you get over ?", "⏳ What did you put off that you need to do?", "🙅 Have you ever turned down an invitation?", "🧑‍🤝‍🧑 Who do you get on with best in class?", "🚀 What will you never give up ?"], "sound": ["In phrasal verbs, the particle is often stressed: set UP · pick it UP", "Say it! Don’t give UP ! · Turn it OFF !"], "rtitle": "The Last Day of School", "rsub": "A short story about friendship, goodbyes and new beginnings", "paras": ["On the last day of school, Daniela woke up early. She couldn’t believe the year was over. She put on her uniform for the last time and looked at the photo on her wall: her, Kevin and Ana on the first day, all smiling and nervous.", "At school, the classroom was full of noise. Kevin had set up a music speaker, and Ana was handing out cookies. “We ran out of chocolate ones,” she laughed. “You’re too late!”", "Then their teacher, Miss Rosario, asked everyone to sit down. “This year, you never gave up,” she said. “You found out that English can open doors. Don’t put off your dreams.” Daniela felt a little sad, but also proud.", "After school, the three friends sat under the big mango tree. “Promise we’ll keep in touch,” said Kevin. Ana picked up her phone and took a selfie. “Year one of our adventure,” she smiled. “Many more to come!”"], "pull": "“This year, you never gave up.”", "atitle": "A. Answer the questions.", "qa": ["1. What photo did Daniela have on her wall?", "2. What had Kevin set up?", "3. What did Miss Rosario tell the class?", "4. What did the friends do under the mango tree?"], "qb": ["5. Daniela woke up late. ____", "6. Ana handed out cookies. ____", "7. The friends will go to the same school next year. ____"], "qc": "Find six phrasal verbs in the story.", "ansR": {"1": "her, Kevin and Ana on the first day", "2": "a music speaker", "3": "they never gave up; don’t put off your dreams", "4": "promised to keep in touch and took a selfie", "5": "F", "6": "T", "7": "DS"}, "ansR_raw": "Answers 7: 1 her, Kevin and Ana on the first day · 2 a music speaker · 3 they never gave up; don’t put off your dreams · 4 promised to keep in touch and took a selfie · 5 F · 6 T · 7 DS", "sub": "Phrasal verbs, and writing that people want to read"}];